import * as React from 'react';
import { expect, it, describe, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as BaseFieldControl } from './base/FieldControl';

afterEach(() => cleanup());

const variants: Array<[string, any]> = [
  ['head', Field.Control],
  ['base', BaseFieldControl],
];

describe.each(variants)('%s', (_label, Control) => {
  it('remount with empty controlled value after control was filled', () => {
    let setValue!: (v: string) => void;
    let setShown!: (v: boolean) => void;
    function App() {
      const [value, sv] = React.useState('foo');
      const [shown, ss] = React.useState(true);
      setValue = sv;
      setShown = ss;
      return (
        <Field.Root data-testid="root">
          {shown ? <Control value={value} onValueChange={sv} /> : null}
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    console.log(_label, 'initial filled', root.hasAttribute('data-filled'));
    act(() => setShown(false));
    act(() => setValue(''));
    act(() => setShown(true));
    console.log(_label, 'after remount empty filled', root.hasAttribute('data-filled'));
  });

  it('controlled prevented input', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), {
      capture: true,
      once: true,
    });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    console.log(
      _label,
      'prevented controlled: validate calls',
      validate.mock.calls.length,
      'server error shown',
      !!screen.queryByText('Server error'),
    );
  });

  it('async validation pending then programmatic change', async () => {
    const resolvers: Array<(v: string | null) => void> = [];
    const validate = vi.fn(
      (v: unknown) => new Promise<string | null>((r) => resolvers.push(r)),
    );
    let setValue!: (v: string) => void;
    function App() {
      const [value, sv] = React.useState('');
      setValue = sv;
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={sv} />
          <Field.Error data-testid="err" />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'bad' } });
    act(() => setValue('good'));
    console.log(_label, 'validate calls', validate.mock.calls.map((c) => c[0]));
    await act(async () => {
      resolvers[0]?.('bad is invalid');
    });
    console.log(_label, 'after stale resolve invalid?', screen.getByTestId('root').getAttribute('data-invalid'));
  });
});

