import * as React from 'react';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { afterEach, it } from 'vitest';
import { Field } from '@base-ui/react/field';
afterEach(cleanup);

it('f4 cancel uncontrolled', () => {
  render(
    <Field.Root data-testid="root" validationMode="onChange">
      <Field.Control defaultValue="x" required onValueChange={(v, d) => { if (v === 'a') d.cancel(); }} />
      <Field.Error match="valueMissing">Required</Field.Error>
    </Field.Root>,
  );
  const c = screen.getByRole('textbox') as HTMLInputElement;
  fireEvent.change(c, { target: { value: '' } });
  console.log('F4 after empty', c.getAttribute('aria-invalid'), !!screen.queryByText('Required'));
  fireEvent.change(c, { target: { value: 'a' } });
  console.log('F4 after a', c.value, c.getAttribute('aria-invalid'), !!screen.queryByText('Required'), screen.getByTestId('root').getAttribute('data-filled'));
});

it('f5 remount', () => {
  let setV: any, setS: any;
  function App() {
    const [v, sv] = React.useState('');
    const [s, ss] = React.useState(true);
    setV = sv; setS = ss;
    return (
      <Field.Root data-testid="root">
        {s ? <Field.Control value={v} onValueChange={sv} /> : null}
      </Field.Root>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
  console.log('F5 typed', screen.getByTestId('root').getAttribute('data-filled'));
  act(() => setS(false));
  act(() => setV(''));
  act(() => setS(true));
  console.log('F5 remount', (screen.getByRole('textbox') as HTMLInputElement).value, screen.getByTestId('root').getAttribute('data-filled'));
});
EOF
